const SIMKOPDES_ARTICLES=[{"id": "n-simkopdes-1", "title": "Hackathon Digital Cooperatives 2026 Lahirkan Tiga Solusi Terbaik untuk Mendorong Transformasi Koperasi Indonesia", "category": "Kabar SIMKOPDES", "date": "2026-07-16", "excerpt": "Kemenkop dan PEBS FEB UI memilih tiga inovasi digital untuk membantu koperasi memperbaiki operasional, tata kelola, dan layanan anggota.", "body": "Kementerian Koperasi bersama PEBS FEB Universitas Indonesia mengumumkan tiga pemenang Hackathon Digital Cooperatives 2026. Kompetisi nasional ini mempertemukan mahasiswa, pelaku startup, profesional, dan talenta teknologi untuk mengembangkan solusi bagi kebutuhan koperasi.\n\nTim Daulat meraih juara pertama melalui Pramana AI. Tim JJJ Labs menempati posisi kedua dengan Simulasi Koperasi. Posisi ketiga diraih Koperasi Link (Koplink), yang mengembangkan platform untuk mengoordinasikan rantai pasok lokal bagi SPPG. Seleksi pemenang mencakup penilaian ide, pendampingan, dan penjurian lintas bidang.\n\nInovasi tersebut diarahkan untuk mempermudah pekerjaan koperasi, memperbaiki pengelolaan, serta memperluas layanan anggota dan partisipasi generasi muda. Peserta juga mendapat pembekalan mengenai teknologi, pengembangan produk, dan bisnis. Kemenkop berencana melanjutkan pembinaan serta membuka peluang penerapan solusi melalui kemitraan agar hasil kompetisi dapat digunakan oleh koperasi.", "source": "SIMKOPDES · ringkasan berita", "sourceUrl": "https://simkopdes.go.id/pers/berita/detail/14/hackathon-digital-cooperatives-2026-lahirkan-tiga-solusi-terbaik-untuk-mendorong-transformasi-koperasi-indonesia", "image": "asset:news1", "status": "published", "sample": false}, {"id": "n-simkopdes-2", "title": "Hari Ini Presiden RI Resmikan 80.000 Kopdes Merah Putih", "category": "Kabar SIMKOPDES", "date": "2026-06-16", "excerpt": "Rencana peluncuran kelembagaan koperasi di Bentangan, Klaten, menjadi bagian dari upaya memperkuat pangan dan perekonomian desa.", "body": "Berita ini membahas persiapan peluncuran kelembagaan 80.000 Koperasi Desa/Kelurahan Merah Putih oleh Presiden Prabowo Subianto di Bentangan, Klaten, Jawa Tengah, yang dijadwalkan pada 21 Juli 2025. Program tersebut diarahkan untuk memperkuat ketahanan pangan serta kegiatan ekonomi masyarakat melalui koperasi.\n\nMenjelang kegiatan, sejumlah menteri meninjau lokasi. Zulkifli Hasan, Budi Arie Setiadi, dan Yandri Susanto termasuk pejabat yang memeriksa kesiapan kantor koperasi serta pelaksanaan acara. Panitia diminta menjaga ketertiban karena peluncuran akan dihadiri banyak undangan, termasuk kepala desa.\n\nPembentukan koperasi melibatkan koordinasi kementerian, lembaga, pemerintah provinsi, dan pemerintah kabupaten/kota. Sejumlah BUMN di bidang pangan, pupuk, energi, perbankan, logistik, dan telekomunikasi juga menjadi bagian dari dukungan program. Peluncuran tersebut diposisikan sebagai langkah untuk mendorong kemandirian ekonomi masyarakat desa.", "source": "SIMKOPDES · ringkasan berita", "sourceUrl": "https://simkopdes.go.id/pers/berita/detail/13/hari-ini-presiden-ri-resmikan-80000-kopdes-merah-putih", "image": "asset:news2", "status": "published", "sample": false}, {"id": "n-simkopdes-3", "title": "Prabowo Launching 80.000 Kopdes Merah Putih di Klaten Hari Ini", "category": "Kabar SIMKOPDES", "date": "2026-06-16", "excerpt": "Peluncuran pada 21 Juli 2025 dipersiapkan di Bentangan, Klaten, untuk mendukung kemandirian pangan dan ekonomi desa berbasis koperasi.", "body": "Presiden Prabowo Subianto dijadwalkan meluncurkan kelembagaan 80.000 Koperasi Desa/Kelurahan Merah Putih di Bentangan, Klaten, Jawa Tengah, pada 21 Juli 2025. Laporan menjelang acara ini menjelaskan bahwa koperasi diharapkan membantu memperkuat kemandirian pangan dan ekonomi desa.\n\nJadwal peluncuran disampaikan Menteri Koordinator Bidang Pangan Zulkifli Hasan saat meninjau persiapan. Presiden telah berangkat ke Jawa Tengah pada 19 Juli 2025. Sehari sebelum peluncuran, Zulkifli Hasan, Menteri Koperasi Budi Arie Setiadi, dan Menteri Desa Yandri Susanto memeriksa kesiapan lokasi KDMP Bentangan.\n\nPersiapan mencakup pengecekan lokasi, koordinasi panitia, dan keterlibatan warga. Ketertiban acara menjadi perhatian karena banyak kepala desa dijadwalkan hadir. Program koperasi ini merupakan hasil kerja bersama lintas kementerian, lembaga, pemerintah daerah, serta BUMN yang mendukung kebutuhan operasional dan layanan koperasi.", "source": "SIMKOPDES · ringkasan berita", "sourceUrl": "https://simkopdes.go.id/pers/berita/detail/12/prabowo-launching-80000-kopdes-merah-putih-di-klaten-hari-ini", "image": "asset:news3", "status": "published", "sample": false}];

