function policyFor(p){const policy=p.subsidy||(/minyak\s*kita/i.test(p.name)?'minyakita':/beras.*sphp|sphp.*beras/i.test(p.name)?'sphp':/\blpg\b|elpiji/i.test(p.name)?'lpg':/raja gula|gula pasir/i.test(p.name)?'gula':'none');return {minyakita:{kind:'minyakita',max:1,short:'Maks. 1 / pembeli / hari',detail:'Minyakita maksimal 1 kemasan per pembeli per hari.',kk:true},sphp:{kind:'sphp',max:1,short:'Maks. 1 / pembeli / hari',detail:'Beras SPHP maksimal 1 kemasan per pembeli per hari.',kk:true},lpg:{kind:'lpg',max:1,short:'Maks. 1 / pembeli / minggu',detail:'LPG maksimal 1 tabung per pembeli per minggu.'},pupuk:{kind:'pupuk',max:null,short:'Sesuai alokasi poktan',detail:'Pupuk sesuai alokasi kelompok tani (poktan) dan e-Pubers.'},gula:{kind:'gula',max:null,short:'Tanpa batas pembelian',detail:'Gula pasir tidak memiliki pembatasan pembelian.'}}[policy]||null}
function plannedMax(p){return Math.min(p.stock??1000000,policyFor(p)?.max??1000000)}
