function policyDetail(p){const r=policyFor(p);return r?'<div class="policy-detail"><b>Ketentuan penjualan</b><br>'+esc(r.detail)+(r.kk?'<br>Bawa KK untuk pembelian di gerai, sesuai informasi pada pamflet.':'')+'<br><span style="font-size:10px">Petugas gerai memeriksa ketentuan pembelian; catatan ini tidak mencatat transaksi.</span></div>':''}
