const oldShoppingText=shoppingText;shoppingText=function(){return oldShoppingText()+'\n\nKETENTUAN BARANG SUBSIDI\nMinyakita: maks. 1 kemasan / pembeli / hari.\nBeras SPHP: maks. 1 kemasan / pembeli / hari.\nPupuk: sesuai alokasi poktan dan e-Pubers.\nLPG: maks. 1 tabung / pembeli / minggu.\nGula pasir: tidak ada pembatasan.\nMinyakita dan SPHP: bawa KK sesuai pamflet.\nPetugas gerai memeriksa batas pembelian.'};
const oldProductForm=productForm;productForm=function(id){oldProductForm(id);const p=state.products.find(p=>p.id===id),f=document.querySelector('#modal form'),grid=f.querySelector('.form-grid');grid.insertAdjacentHTML('beforeend','<label class="full">Ketentuan penjualan<select name="subsidy">'+options([['none','Tidak ada ketentuan khusus'],['minyakita','Minyakita · 1 / pembeli / hari'],['sphp','SPHP · 1 / pembeli / hari'],['pupuk','Pupuk · sesuai alokasi'],['lpg','LPG · 1 / pembeli / minggu'],['gula','Gula pasir · tanpa pembatasan']],p?.subsidy||'none')+'</select></label>')};
function showGuide(){const el=document.getElementById('modal');el.classList.remove('pamflet-dialog');el.classList.add('guide-dialog');modal('Selamat datang di SI-BANYU.','<div class="guide-intro"><img src="'+BUILTIN_IMAGES.kopdes+'" alt="Logo Kopdes Merah Putih"><div><h3>Koperasi lebih dekat.<br><em class="editorial">Kebutuhan lebih terencana.</em></h3><p>Kenali fungsi website dan mulai dalam beberapa langkah.</p></div></div><p class="guide-purpose">Website ini membantu kamu mengenal koperasi, melihat barang dan perkiraan harga, menyimpan catatan belanja, serta mengikuti kabar koperasi.</p><div class="guide-steps">'+[['Buka katalog','Cari barang atau pilih kategorinya. Ketuk foto untuk melihat detail dan aturan pembelian.'],['Masukkan ke catatan','Tekan +, atur jumlah, dan tulis pengingat agar tidak ada kebutuhan yang terlupa.'],['Lihat perkiraan biaya','Buka ikon keranjang. Cek total, simpan daftar, atau centang barang yang sudah ditemukan.'],['Kunjungi gerai','Konfirmasi harga dan stok di gerai. Perhatikan batas subsidi dan bawa KK bila diperlukan.']].map(([a,b],i)=>'<div class="guide-step"><div class="step-index">0'+(i+1)+'</div><h4>'+a+'</h4><p>'+b+'</p></div>').join('')+'</div><div class="guide-reminder">'+icon('info')+'<span>Catatan belanja tidak mengirim pesanan atau pembayaran. Datamu tersimpan di browser ini. Panduan ini bisa dibuka lagi lewat tombol <b>?</b>.</span></div><div class="guide-admin-note"><b>Untuk pengelola:</b> pilih Admin untuk mengelola stok, produk, berita, dan profil. Gunakan akun pengelola yang telah diaktifkan untuk SI-BANYU.</div><div class="form-actions"><button class="btn light" data-v2="guide-catalog">Buka katalog '+icon('arrow')+'</button><button class="btn" data-action="close-modal">Mengerti, mulai pakai '+icon('check')+'</button></div>');el.dataset.guide='yes';document.body.classList.add('guide-open')}
