BUILTIN_IMAGES.kopdeskel='data:image/png;base64,';
/* Shopping notes exported as a real PNG receipt, with the supplied Kopdeskel identity. */
const RECEIPT_WIDTH=420,RECEIPT_SCALE=2,RECEIPT_PAGE_HEIGHT=2800;
const RECEIPT_FONT='"SFMono-Regular",Menlo,Consolas,monospace';
let receiptPreview=null,receiptBusy=false;
function receiptDate(at){
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(at);
 const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));
 return {label:new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'short',year:'numeric'}).format(at)+' · '+p.hour+':'+p.minute+' WIB',file:p.year+'-'+p.month+'-'+p.day+'-'+p.hour+p.minute};
}
function receiptWrap(ctx,value,width,size=14,weight=400){
 ctx.font=weight+' '+size+'px '+RECEIPT_FONT;
 const result=[];
 for(const paragraph of String(value??'').replace(/\r/g,'').split('\n')){
  let line='';
  for(const word of paragraph.match(/\S+/g)||[]){
   if(ctx.measureText((line?line+' ':'')+word).width<=width){line+=(line?' ':'')+word;continue}
   if(line){result.push(line);line=''}
   if(ctx.measureText(word).width<=width){line=word;continue}
   for(const char of Array.from(word)){if(line&&ctx.measureText(line+char).width>width){result.push(line);line=''}line+=char}
  }
  result.push(line);
 }
 return result;
}
function receiptBlock(ctx,width){
 const block={height:0,commands:[]};
 block.text=function(value,{size=14,weight=400,color='#282525',lineHeight=size+6,x=0,maxWidth=width,align='left',gap=0}={}){
  const lines=receiptWrap(ctx,value,maxWidth,size,weight);
  for(const line of lines){block.commands.push({type:'text',text:line,x,y:block.height,size,weight,color,align});block.height+=lineHeight}
  block.height+=gap;return block;
 };
 block.line=function(gap=15){block.height+=gap;block.commands.push({type:'line',x:0,y:block.height,width});block.height+=gap;return block};
 block.pair=function(label,value,{size=14,weight=400,color='#282525',gap=6}={}){
  ctx.font=weight+' '+size+'px '+RECEIPT_FONT;
  const amountWidth=ctx.measureText(value).width;
  const y=block.height;
  block.text(label,{size,weight,color,maxWidth:Math.max(60,width-amountWidth-16)});
  block.commands.push({type:'text',text:value,x:width,y,size,weight,color,align:'right'});
  block.height+=gap;return block;
 };
 return block;
}
function receiptLayout(snapshot,at,ctx){
 const width=RECEIPT_WIDTH-64;
 const date=receiptDate(at);
 const header=receiptBlock(ctx,width);
 header.height=128;
 header.text(snapshot.settings.cooperativeName.toUpperCase(),{size:18,weight:700,align:'center',x:width/2,gap:8});
 if(snapshot.settings.address)header.text(snapshot.settings.address,{size:11,lineHeight:17,align:'center',x:width/2,gap:8});
 header.line(10).text('CATATAN BELANJA',{size:18,weight:700,align:'center',x:width/2,gap:3});
 header.text(date.label,{size:11,align:'center',x:width/2,gap:3});
 header.text('Disusun sebelum berbelanja',{size:11,color:'#776a60',align:'center',x:width/2});
 header.line(12);
 const blocks=[],items=snapshot.selection.map(x=>({...x,product:snapshot.products.find(p=>p.id===x.productId)})).filter(x=>x.product);
 let total=0,unknown=false;
 for(const item of items){
  const p=item.product,b=receiptBlock(ctx,width);
  b.commands.push({type:'check',x:0,y:3,checked:item.checked});
  b.text(p.name,{x:26,maxWidth:width-26,size:15,weight:700,lineHeight:21,gap:5});
  const subtotal=p.price===null?'Belum diisi':money(p.price*item.quantity);
  const detail=item.quantity+' × '+p.unit+' @ '+(p.price===null?'harga belum diisi':money(p.price));
  b.pair(detail,subtotal,{size:12,gap:5});
  if(item.note)b.text('Catatan: '+item.note,{size:12,color:'#675a50',lineHeight:18,gap:3});
  const rule=policyFor(p);
  if(rule){b.text(rule.detail,{size:11,lineHeight:17,color:'#8b3a36',gap:2});if(rule.kk)b.text('Bawa KK saat membeli di gerai.',{size:11,lineHeight:17,color:'#8b3a36',gap:2})}
  if(p.review)b.text('Periksa rincian harga/kemasan di gerai.',{size:11,lineHeight:17,color:'#675a50',gap:2});
  if(item.checked)b.text('Sudah dicentang dalam daftar',{size:11,lineHeight:17,color:'#675a50',gap:2});
  b.line(12);blocks.push(b);
  if(p.price===null)unknown=true;else total+=p.price*item.quantity;
 }
 const totals=receiptBlock(ctx,width);
 totals.pair('Jumlah kemasan',String(items.reduce((n,x)=>n+x.quantity,0)),{size:13,gap:2});
 totals.pair('Jenis produk',String(items.length),{size:13,gap:10});
 totals.pair('ESTIMASI TOTAL',money(total),{size:16,weight:700,gap:5});
 if(unknown)totals.text('Belum termasuk barang yang harganya belum diisi.',{size:11,color:'#8b3a36',lineHeight:17,gap:7});
 if(snapshot.budget!==null){
  totals.pair('Anggaran',money(snapshot.budget),{size:13,gap:2});
  totals.pair(total>snapshot.budget?'Melebihi anggaran':'Sisa anggaran',money(Math.abs(snapshot.budget-total)),{size:13,gap:2});
 }
 totals.line(12);blocks.push(totals);
 if(snapshot.shoppingNote){const notes=receiptBlock(ctx,width);notes.text('PENGINGAT BELANJA',{size:13,weight:700,gap:6});notes.text(snapshot.shoppingNote,{size:12,lineHeight:19});notes.line(12);blocks.push(notes)}
 const footer=receiptBlock(ctx,width);
 footer.text('Harga dan stok dikonfirmasi di gerai.',{size:11,align:'center',x:width/2,lineHeight:17,gap:3});
 footer.text('Catatan pribadi, bukan bukti pembayaran.',{size:11,align:'center',x:width/2,lineHeight:17,gap:11});
 footer.text('Sampai jumpa di koperasi!',{size:12,weight:700,align:'center',x:width/2,gap:3});
 footer.text('@kdkmp.banyurojo',{size:11,color:'#8b3a36',align:'center',x:width/2});
 const capacity=RECEIPT_PAGE_HEIGHT-header.height-footer.height-100,pages=[];
 let current=[],height=0;
 for(const block of blocks){if(current.length&&height+block.height>capacity){pages.push({blocks:current,height});current=[];height=0}current.push(block);height+=block.height}
 if(current.length)pages.push({blocks:current,height});
 return {header,footer,pages,date,itemCount:items.length,quantity:items.reduce((n,x)=>n+x.quantity,0),total,unknown};
}
function drawReceiptBlock(ctx,block,offsetY){
 for(const c of block.commands){
  if(c.type==='text'){ctx.fillStyle=c.color;ctx.font=c.weight+' '+c.size+'px '+RECEIPT_FONT;ctx.textAlign=c.align;ctx.textBaseline='top';ctx.fillText(c.text,32+c.x,offsetY+c.y)}
  if(c.type==='line'){ctx.save();ctx.strokeStyle='#b8a99b';ctx.lineWidth=.8;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(32,offsetY+c.y);ctx.lineTo(32+c.width,offsetY+c.y);ctx.stroke();ctx.restore()}
  if(c.type==='check'){ctx.save();ctx.strokeStyle='#5f514b';ctx.lineWidth=1.2;ctx.strokeRect(32+c.x,offsetY+c.y,13,13);if(c.checked){ctx.lineWidth=1.7;ctx.beginPath();ctx.moveTo(34+c.x,offsetY+c.y+7);ctx.lineTo(37+c.x,offsetY+c.y+10);ctx.lineTo(43+c.x,offsetY+c.y+3);ctx.stroke()}ctx.restore()}
 }
}
function loadReceiptLogo(){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Logo belum dapat dimuat. Coba simpan gambar sekali lagi.'));img.src=BUILTIN_IMAGES.kopdeskel})}
async function makeShoppingReceipt(snapshot,at=new Date()){
 if(!snapshot.selection.length)throw new Error('Pilih barang dari katalog terlebih dahulu.');
 await document.fonts?.ready;
 const logo=await loadReceiptLogo(),measure=document.createElement('canvas'),layout=receiptLayout(snapshot,at,measure.getContext('2d')),images=[];
 for(let i=0;i<layout.pages.length;i++){
  const page=layout.pages[i],height=32+layout.header.height+(layout.pages.length>1?28:0)+page.height+16+layout.footer.height+36;
  const canvas=document.createElement('canvas');canvas.width=RECEIPT_WIDTH*RECEIPT_SCALE;canvas.height=Math.ceil(height)*RECEIPT_SCALE;
  const ctx=canvas.getContext('2d');ctx.scale(RECEIPT_SCALE,RECEIPT_SCALE);ctx.fillStyle='#fffdf7';ctx.fillRect(0,0,RECEIPT_WIDTH,height);
  ctx.save();ctx.globalAlpha=.065;
  for(let y=340;y<height-75;y+=330)ctx.drawImage(logo,(RECEIPT_WIDTH-270)/2,y-50,270,270);
  ctx.restore();
  ctx.drawImage(logo,(RECEIPT_WIDTH-146)/2,14,146,146);
  let y=32;drawReceiptBlock(ctx,layout.header,y);y+=layout.header.height;
  if(layout.pages.length>1){ctx.font='11px '+RECEIPT_FONT;ctx.textAlign='center';ctx.fillStyle='#78665a';ctx.fillText('HALAMAN '+(i+1)+' / '+layout.pages.length,RECEIPT_WIDTH/2,y+3);y+=28}
  for(const b of page.blocks){drawReceiptBlock(ctx,b,y);y+=b.height}
  y+=16;drawReceiptBlock(ctx,layout.footer,y);
  const dataUrl=canvas.toDataURL('image/png');if(dataUrl==='data:,')throw new Error('Gambar terlalu besar untuk perangkat ini. Kurangi jumlah catatan dan coba lagi.');
  images.push({dataUrl,width:canvas.width,height:canvas.height,name:'catatan-belanja-banyurojo-'+layout.date.file+(layout.pages.length>1?'-'+(i+1):'')+'.png'});
  canvas.width=0;canvas.height=0;
 }
 return {images,total:layout.total,itemCount:layout.itemCount,quantity:layout.quantity};
}
function renderReceiptPreview(){
 if(!receiptPreview)return;
 const {images,index}=receiptPreview,page=images[index],multiple=images.length>1;
 const body=document.querySelector('#modal .dialog-body');
 body.innerHTML='<div class="receipt-save-bar"><div><strong>Siap dibawa saat belanja.</strong><p>Nama barang, jumlah, harga, dan pengingat tersimpan dalam gambar.</p></div><a class="btn" data-receipt-download href="'+page.dataUrl+'" download="'+esc(page.name)+'">'+icon('download')+' '+(multiple?'Unduh halaman '+(index+1):'Unduh PNG')+'</a></div>'+(multiple?'<div class="receipt-pages"><button class="btn light small" data-receipt="previous" '+(index===0?'disabled':'')+'>'+icon('back')+' Sebelumnya</button><span aria-live="polite">Halaman '+(index+1)+' dari '+images.length+'</span><button class="btn light small" data-receipt="next" '+(index===images.length-1?'disabled':'')+'>Berikutnya '+icon('arrow')+'</button></div><p class="receipt-mobile-tip">Daftar panjang dibagi menjadi beberapa gambar. Unduh tiap halaman agar semua barang tersimpan.</p>':'')+'<div class="receipt-image-wrap"><img class="receipt-image" src="'+page.dataUrl+'" width="'+page.width+'" height="'+page.height+'" alt="Catatan belanja KDKMP Banyurojo'+(multiple?', halaman '+(index+1):'')+'. '+receiptPreview.itemCount+' jenis produk. Estimasi total '+esc(money(receiptPreview.total))+'."></div><p class="receipt-mobile-tip">Di iPhone, kamu juga bisa tekan dan tahan gambar untuk menyimpannya ke Foto.</p>';
 document.getElementById('modal').scrollTop=0;
}
async function showShoppingReceipt(trigger){
 if(receiptBusy)return;
 receiptBusy=true;const label=trigger?.innerHTML;
 if(trigger){trigger.disabled=true;trigger.innerHTML='Menyiapkan gambar…'}
 try{
  const result=await makeShoppingReceipt(structuredClone(state));
  receiptPreview={...result,index:0};
  modal('Gambar catatan belanja','');
  document.getElementById('modal').classList.add('receipt-dialog');
  renderReceiptPreview();
 }catch(err){toast(err.message||'Gambar belum berhasil dibuat. Coba lagi.',true)}
 finally{receiptBusy=false;if(trigger?.isConnected){trigger.disabled=false;trigger.innerHTML=label}}
}
const renderCartBeforeReceipt=renderCart;
renderCart=function(){renderCartBeforeReceipt();const b=document.querySelector('#cartDrawer [data-action="download-list"]');if(b){b.innerHTML=icon('image')+' Simpan gambar';b.setAttribute('aria-label','Simpan catatan belanja sebagai gambar PNG')}const text=document.querySelector('#cartDrawer .shopping-note .row span');if(text)text.innerHTML='Tersimpan di browser ini.<br>Simpan gambar untuk dibawa.'};
function refreshCartAmounts(){
 const drawer=document.getElementById('cartDrawer');
 for(const input of drawer.querySelectorAll('[data-quantity]')){const p=state.products.find(p=>p.id===input.dataset.quantity),item=state.selection.find(x=>x.productId===input.dataset.quantity);if(!p||!item)continue;const row=input.closest('.cart-item');row.querySelector('.cart-subtotal').textContent=p.price===null?'Belum diketahui':money(p.price*item.quantity);row.querySelector('[data-delta="1"]').disabled=item.quantity>=plannedMax(p)}
 const total=selectionTotal(),count=state.selection.reduce((n,x)=>n+x.quantity,0),amount=drawer.querySelector('.cart-total'),countLabel=drawer.querySelector('.cart-total-label+div');
 if(amount)amount.textContent=money(total);if(countLabel)countLabel.textContent=count+' kemasan · '+state.selection.length+' jenis produk';
 const note=drawer.querySelector('.shopping-note');if(!note)return;
 let feedback=note.querySelector('p:not(.rule-note-short)');
 if(state.budget===null){feedback?.remove();return}
 if(!feedback){feedback=document.createElement('p');feedback.style.cssText='font-size:10px;margin-top:10px';note.append(feedback)}
 feedback.style.color=total>state.budget?'var(--red)':'var(--green)';feedback.textContent=total>state.budget?'Melebihi anggaran '+money(total-state.budget):'Sisa dari anggaran '+money(state.budget-total);
}
updateSelectionQuantity=function(id,quantity,preserveInput=false){
 const p=state.products.find(p=>p.id===id);if(!p)return;
 if(quantity===0&&!preserveInput)return removeFromSelection(id);
 if(!Number.isSafeInteger(quantity)||quantity<1||quantity>plannedMax(p)){toast(policyFor(p)?.max?policyFor(p).detail:'Jumlah harus bulat dan tidak melebihi stok.',true);const input=document.querySelector('#cartDrawer [data-quantity="'+CSS.escape(id)+'"]');if(input)input.value=state.selection.find(x=>x.productId===id)?.quantity||1;return}
 commit(s=>{const x=s.selection.find(x=>x.productId===id);if(x){x.quantity=quantity;x.checked=false}},'',false);
 if(preserveInput)refreshCartAmounts();else renderCart();
};
function updateShoppingBudget(el){const value=el.value===''?null:Number(el.value);if(value!==null&&(!Number.isSafeInteger(value)||value<0||value>1e9)){toast('Anggaran harus bilangan bulat rupiah yang tidak negatif.',true);el.value=state.budget??'';return}commit(s=>{s.budget=value},'',false);refreshCartAmounts()}
