// Production administration: verified server lease, no browser-only demo login.
let adminVerified=false, adminSessionId='', cloudRevision=null, adminBusy=false, authEpoch=0, booting=true;
let lastPublicContent=null, touchTimer=null, touchRunning=false, lastTouchSent=0, lastStorageWrite=0;
const ACTIVITY_KEY='si-banyu-admin-activity', LOGOUT_KEY='si-banyu-admin-logout';
const idle=new IdleSession({
  read(){try{return JSON.parse(localStorage.getItem(ACTIVITY_KEY)||'null')}catch{return null}},
  write(stamp){if(Date.now()-lastStorageWrite<1000)return;lastStorageWrite=Date.now();try{localStorage.setItem(ACTIVITY_KEY,JSON.stringify(stamp))}catch{}},
  onExpire(){void signOutAdmin('Sesi berakhir setelah 10 menit tanpa aktivitas. Silakan masuk kembali.');}
});
isAdmin=function(){return adminVerified && idle.check()};

function persistCartState(s){
  localStorage.setItem(KEY,JSON.stringify({selection:s.selection,shoppingNote:s.shoppingNote,budget:s.budget}));
}
function restorePersonalCart(){
  try{const cart=JSON.parse(localStorage.getItem(KEY)||'null');if(cart){const test=structuredClone(state);test.selection=cart.selection||[];test.shoppingNote=cart.shoppingNote||'';test.budget=cart.budget??null;validateData(test);cleanSelection(test);state=test}}
  catch{startupWarning='Catatan pada browser tidak dapat dibaca. Katalog tetap dapat digunakan.'}
}
function applyCloudContent(content){
  const next={...seedData(),...structuredClone(content),selection:state.selection,shoppingNote:state.shoppingNote,budget:state.budget};
  validateData(next);cleanSelection(next);state=next;try{persistCartState(next)}catch{};
}
function publicProjection(content){
  const p=structuredClone(content);p.products=p.products.filter(x=>x.active);p.articles=p.articles.filter(x=>x.status==='published');p.members=p.members.filter(x=>x.active);p.logs=[];return p;
}
async function refreshPublicContent(){
  if(!configured || adminVerified)return;
  try{const result=await rpc('si_banyu_get_public_content');if(result?.content&&!adminVerified){lastPublicContent=result.content;applyCloudContent(result.content);render();if(cartOpen)renderCart()}}
  catch{if(!lastPublicContent)toast('Katalog awal ditampilkan. Data server belum dapat dimuat.',true)}
}
function saveActivity(){
  if(!adminVerified||!idle.check()||!configured)return;
  if(touchTimer!==null)return;
  touchTimer=setTimeout(async()=>{
    touchTimer=null;if(!adminVerified||!idle.check()||touchRunning)return;
    touchRunning=true;
    try{await rpc('si_banyu_touch_session');lastTouchSent=Date.now()}
    catch(error){if(error.code==='42501')void signOutAdmin(error.message)}
    finally{touchRunning=false}
  },Math.max(0,1000-(Date.now()-lastTouchSent)));
}
function recordAdminActivity(event){
  if(!event.isTrusted || document.visibilityState==='hidden' || !location.hash.startsWith('#admin'))return;
  if(adminVerified && idle.activity())saveActivity();
}
for(const type of ['pointerdown','pointermove','keydown','wheel','touchstart','input'])document.addEventListener(type,recordAdminActivity,{capture:true,passive:true});
for(const type of ['focus','pageshow'])window.addEventListener(type,()=>{if(adminVerified)idle.sync()});
document.addEventListener('visibilitychange',()=>{if(adminVerified)idle.sync()});
window.addEventListener('storage',event=>{
  if(event.key===ACTIVITY_KEY&&adminVerified)idle.sync();
  if(event.key===LOGOUT_KEY&&adminVerified){try{const v=JSON.parse(event.newValue||'null');if(v?.sid===adminSessionId)void signOutAdmin('Sesi admin telah berakhir.')}catch{}}
});

async function signOutAdmin(message='Keluar dari admin.',notify=true){
  const oldSid=adminSessionId, epoch=++authEpoch;
  adminVerified=false;adminSessionId='';adminBusy=false;idle.stop();
  if(touchTimer!==null)clearTimeout(touchTimer);touchTimer=null;
  try{localStorage.setItem(LOGOUT_KEY,JSON.stringify({sid:oldSid,at:Date.now()}))}catch{}
  try{closeModal();closeCart()}catch{}
  applyCloudContent(lastPublicContent || publicProjection(contentOf(seedData())));
  if(location.hash.startsWith('#admin'))location.hash='admin';render();
  if(notify)toast(message,true);
  if(supabase){
    try{const {data:{session}}=await supabase.auth.getSession();if(authEpoch===epoch && (!oldSid||jwtSessionId(session?.access_token||'')===oldSid)){if(oldSid)await rpc('si_banyu_close_session').catch(()=>{});await supabase.auth.signOut({scope:'local'})}}catch{}
  }
  void refreshPublicContent();
}

async function signInAdmin(email,password,form){
  if(!supabase)return formError(form,'Isi konfigurasi Supabase sebelum menggunakan admin.');
  const button=form.querySelector('[type="submit"]');button.disabled=true;
  const epoch=++authEpoch;
  try{
    const {data,error}=await supabase.auth.signInWithPassword({email,password});
    if(error)throw new Error('Email atau kata sandi tidak sesuai, atau akun belum diaktifkan.');
    const lease=await rpc('si_banyu_open_session');
    const result=await rpc('si_banyu_get_admin_content');
    if(!result?.content)throw new Error('Data awal belum diimpor. Jalankan seed.sql terlebih dahulu.');
    if(epoch!==authEpoch)return;
    adminSessionId=jwtSessionId(data.session.access_token);cloudRevision=Number(result.revision);
    lastStorageWrite=0;adminVerified=true;
    if(!idle.start(adminSessionId,Date.now()))throw new Error('Sesi telah berakhir.');
    applyCloudContent(result.content);location.hash='admin/dashboard';render();toast('Selamat datang di SI-BANYU.');
  }catch(error){
    adminVerified=false;idle.stop();await supabase.auth.signOut({scope:'local'}).catch(()=>{});
    if(form.isConnected)formError(form,error.message||'Tidak dapat masuk.');
  }finally{if(button.isConnected)button.disabled=false;const p=form.elements.password;if(p)p.value=''}
}

async function adminCommit(fn,message='',rerender=true){
  if(!isAdmin()){toast('Sesi admin berakhir. Masuk kembali.',true);return false}
  if(adminBusy){toast('Tunggu penyimpanan yang sedang berjalan.');return false}
  const epoch=authEpoch;adminBusy=true;
  const submit=document.querySelector('#modal[open] form [type="submit"]');if(submit)submit.disabled=true;
  try{
    const next=structuredClone(state);fn(next);cleanSelection(next);validateData(next);
    const content=await uploadContentImages(contentOf(next));
    const saved=await rpc('si_banyu_save_content',{p_content:content,p_expected_revision:cloudRevision});
    if(epoch!==authEpoch||!isAdmin())return false;
    cloudRevision=Number(saved.revision);applyCloudContent(saved.content);
    lastPublicContent=publicProjection(saved.content);
    if(rerender){render();if(cartOpen)renderCart()}else updateCartBadges();
    if(message)toast(message);return true;
  }catch(error){
    if(error.code==='42501'){void signOutAdmin(error.message);return false}
    if(error.cause?.message?.includes('SI_CONFLICT')){
      modal('Data sudah berubah','<p>Admin lain telah menyimpan perubahan. Formulir ini belum disimpan. Salin perubahan pentingmu sebelum memuat data terbaru.</p><div class="form-actions"><button class="btn light" data-action="close-modal">Tutup</button><button class="btn" data-cloud-action="reload">Muat data terbaru</button></div>');
    }else{const form=document.querySelector('#modal[open] form');if(form)formError(form,error.message);else toast(error.message,true)}
    return false;
  }finally{adminBusy=false;if(submit?.isConnected)submit.disabled=false}
}
document.addEventListener('click',async event=>{
  if(!event.target.closest('[data-cloud-action="reload"]')||!isAdmin())return;
  try{const result=await rpc('si_banyu_get_admin_content');cloudRevision=Number(result.revision);applyCloudContent(result.content);closeModal();render();toast('Data terbaru dimuat.')}catch(error){toast(error.message,true)}
});

