adminBackup=function(){return adminHead('Data yang bisa dibawa.','Backup katalog, stok, profil, struktur, berita, dan riwayat pengelolaan.')+'<section class="admin-panel"><h2>Backup & pemulihan</h2><p>Data pengelolaan tersimpan di server. Backup JSON memuat data serta tautan foto; salin berkas foto melalui Supabase Storage untuk cadangan media terpisah.</p><div class="backup-zone"><h3>Simpan salinan data</h3><p>Unduh data yang sedang dimuat pada sesi admin ini.</p><button class="btn" data-action="export-data">'+icon('download')+' Unduh backup JSON</button></div><div class="backup-zone"><h3>Pulihkan dari backup</h3><p>Isi berkas diperiksa sebelum mengganti konten server. Catatan belanja pembeli tidak diubah.</p><button class="btn light" data-action="import-data">'+icon('upload')+' Pilih file JSON</button></div><div class="backup-zone" style="border-color:#e5c1ba"><h3 class="text-red">Kembali ke konten awal</h3><p>Perubahan katalog dan konten di server akan diganti. Unduh backup sebelum melanjutkan bila masih diperlukan.</p><button class="btn danger" data-action="reset-data">Reset konten server</button></div></section>'};
exportApplicationData=async function(){if(!isAdmin())return;download(JSON.stringify({...contentOf(state),selection:[],shoppingNote:'',budget:null},null,2),'backup-si-banyu-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('Backup JSON diunduh.')};
async function restoreAdminSession(){
  if(!supabase)return;
  const epoch=authEpoch;
  try{
    const {data:{session}}=await supabase.auth.getSession();if(!session)return;
    const sid=jwtSessionId(session.access_token);let saved;
    try{saved=JSON.parse(localStorage.getItem(ACTIVITY_KEY)||'null')}catch{}
    if(epoch!==authEpoch)return;
    if(!saved||saved.sid!==sid||!Number.isFinite(saved.at)||Date.now()-saved.at>=ADMIN_IDLE_MS||saved.at>Date.now()+5000){await signOutAdmin('Sesi admin berakhir. Silakan masuk kembali.',false);return}
    const result=await rpc('si_banyu_get_admin_content');if(!result?.content)return;
    if(epoch!==authEpoch)return;
    adminSessionId=sid;cloudRevision=Number(result.revision);adminVerified=true;
    if(!idle.start(sid,saved.at))return;
    applyCloudContent(result.content);render();
  }catch{if(epoch===authEpoch)await signOutAdmin('Sesi admin berakhir. Silakan masuk kembali.',false)}
}
async function startProduction(){
  restorePersonalCart();render();
  await refreshPublicContent();await restoreAdminSession();booting=false;render();if(cartOpen)renderCart();
  if(supabase)supabase.auth.onAuthStateChange((event,session)=>{
    if(event==='SIGNED_OUT'&&adminVerified)queueMicrotask(()=>void signOutAdmin('Sesi admin berakhir.'));
    if((event==='SIGNED_IN'||event==='TOKEN_REFRESHED')&&adminVerified&&jwtSessionId(session?.access_token||'')!==adminSessionId){adminVerified=false;idle.stop();applyCloudContent(lastPublicContent||publicProjection(contentOf(seedData())));render()}
    // TOKEN_REFRESHED/INITIAL_SESSION never count as user activity.
  });
  setInterval(()=>{if(!adminVerified && document.visibilityState==='visible')void refreshPublicContent()},60000);
  if(startupWarning)toast(startupWarning,true);
}
void startProduction();
